async function runAnalysis() {
  // Define Somalia polygon
  const somalia = ee.Geometry.Polygon([
    [[40.98, 11.99], [51.41, 11.99], [51.41, -1.66], [40.98, -1.66], [40.98, 11.99]]
  ]);

  // Load CHIRPS precipitation data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  // Baseline period: March-September for 1981-2021
  const baselineFilter = ee.Filter.and(
    ee.Filter.calendarRange(1981, 2021, 'year'),
    ee.Filter.calendarRange(3, 9, 'month')
  );
  const baselineCol = chirps.filter(bounds).filter(baselineFilter);

  // 2022 period: March-September
  const year2022Filter = ee.Filter.and(
    ee.Filter.calendarRange(2022, 2022, 'year'),
    ee.Filter.calendarRange(3, 9, 'month')
  );
  const year2022Col = chirps.filter(bounds).filter(year2022Filter);

  // Check collection sizes
  const baselineSize = baselineCol.size().getInfo();
  const year2022Size = year2022Col.size().getInfo();

  print(`Baseline images (1981-2021 Mar-Sep): ${baselineSize}`);
  print(`2022 images (Mar-Sep): ${year2022Size}`);

  if (baselineSize === 0 || year2022Size === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // Calculate total precipitation for each period
  const baselineTotal = baselineCol.sum();
  const year2022Total = year2022Col.sum();

  // Calculate baseline average per year (divide by 41 years)
  const baselineAvg = baselineTotal.divide(41);

  // Reduce regions to get mean precipitation values
  const baselineStats = baselineAvg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: somalia,
    scale: 5000,
    maxPixels: 1e9
  });

  const year2022Stats = year2022Total.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: somalia,
    scale: 5000,
    maxPixels: 1e9
  });

  const baselineVal = baselineStats.get('precipitation').getInfo();
  const year2022Val = year2022Stats.get('precipitation').getInfo();

  print(`Baseline avg (1981-2021): ${baselineVal ? baselineVal.toFixed(1) : 'null'} mm`);
  print(`2022 total: ${year2022Val ? year2022Val.toFixed(1) : 'null'} mm`);

  // Check for calculation failures
  if (baselineVal === null || year2022Val === null || 
      isNaN(baselineVal) || isNaN(year2022Val)) {
    print("<answer>C3</answer>");
    return;
  }

  // Check for valid pixels by counting non-zero pixels
  const pixelCount = baselineAvg.gt(0).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: somalia,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  print(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    print("<answer>C2</answer>");
    return;
  }

  // Compare values and determine answer
  const decreasePercent = ((baselineVal - year2022Val) / baselineVal * 100).toFixed(1);
  print(`Change: ${decreasePercent}%`);

  if (year2022Val < baselineVal) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

